569→// --- Helpers ---
570→
571→func nonEmptyLines(data []byte) []string {
572→	var lines []string
573→	for _, line := range strings.Split(string(data), "\n") {
574→		if strings.TrimSpace(line) != "" {
575→			lines = append(lines, line)
576→		}
577→	}
578→	return lines
579→}
580→
581→// assertJSONLines compares actual output lines against expected JSON strings,
582→// using semantic JSON equality (order-independent for object keys).
583→func assertJSONLines(t *testing.T, actual []byte, expected []string) {
584→	t.Helper()
585→
586→	actualLines := nonEmptyLines(actual)
587→
588→	if len(expected) == 0 && len(actualLines) == 0 {
589→		return
590→	}
591→
592→	if len(actualLines) != len(expected) {
593→		t.Fatalf("line count mismatch: got %d, want %d\nactual:\n%s", len(actualLines), len(expected), string(actual))
594→	}
595→
596→	for i := range expected {
597→		var got, want interface{}
598→		if err := json.Unmarshal([]byte(actualLines[i]), &got); err != nil {
599→			t.Fatalf("line %d: failed to parse actual JSON: %v\nline: %s", i, err, actualLines[i])
600→		}
601→		if err := json.Unmarshal([]byte(expected[i]), &want); err != nil {
602→			t.Fatalf("line %d: failed to parse expected JSON: %v\nline: %s", i, err, expected[i])
603→		}
604→		if !reflect.DeepEqual(got, want) {
605→			prettyGot, _ := json.MarshalIndent(got, "", "  ")
606→			prettyWant, _ := json.MarshalIndent(want, "", "  ")
607→			t.Errorf("line %d mismatch:\ngot:\n%s\nwant:\n%s", i, prettyGot, prettyWant)
608→		}
609→	}
610→}
